-- composition of rule kernels common_subexpressions x compressed_materialization (duckdb), template cte_twice
WITH ka AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT LIST_HAS_ALL (ARRAY[a1.c0], CASE WHEN TRUE THEN ARRAY_REVERSE (ARRAY[a1.c0]) ELSE ARRAY[1, 2, 3] END) AS c0, 'ß'::text AS c1 FROM t1 AS a1), kb AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 100::bigint AS c0 UNION SELECT 10::bigint AS c0) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT LIST_HAS_ALL (ARRAY[a1.c0], CASE WHEN TRUE THEN ARRAY_REVERSE (ARRAY[a1.c0]) ELSE ARRAY[1, 2, 3] END) AS c0, 'ß'::text AS c1 FROM t1 AS a1) AS ka) + (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 100::bigint AS c0 UNION SELECT 10::bigint AS c0) AS kb)
